/** Locale manifest (public/i18n/manifest.json), generated by scripts/i18n. Pure builders, testable. */
import { coverage, hashText, type FlatMessages } from "./keys";
import { targetKeys } from "./translate-core";

export type LocaleStatus = "reviewed" | "machine" | "partial";

export interface ManifestEntry {
  status: LocaleStatus;
  /** 0..1 fraction of English keys translated. */
  coverage: number;
  /** Hash of the whole English source this locale was last synced against. */
  sourceHash: string;
  updated: string;
}

export interface Manifest {
  version: 1;
  source: string;
  locales: Record<string, ManifestEntry>;
}

export function sourceHash(enFlat: FlatMessages): string {
  return hashText(Object.keys(enFlat).sort().map((k) => `${k}=${enFlat[k]}`).join("\n"));
}

/** `reviewedKeys`: keys a native speaker has reviewed. Status is "reviewed" only when every key is. */
export function manifestEntry(
  enFlat: FlatMessages,
  flat: FlatMessages,
  opts: { baseStatus: "reviewed" | "machine"; reviewedKeys?: readonly string[]; updated: string; tag?: string },
): ManifestEntry {
  // Coverage counts the keys this locale needs (English plural groups expand to the locale's categories).
  const targets = opts.tag ? targetKeys(opts.tag, enFlat) : enFlat;
  const cov = coverage(targets, flat);
  const reviewed = new Set(opts.reviewedKeys ?? []);
  const allReviewed = opts.baseStatus === "reviewed" || (reviewed.size > 0 && Object.keys(targets).every((k) => reviewed.has(k)));
  const status: LocaleStatus = cov < 1 ? "partial" : allReviewed ? "reviewed" : "machine";
  return { status, coverage: Math.round(cov * 10000) / 10000, sourceHash: sourceHash(enFlat), updated: opts.updated };
}

export function isManifest(v: unknown): v is Manifest {
  if (!v || typeof v !== "object") return false;
  const m = v as Partial<Manifest>;
  return m.version === 1 && typeof m.locales === "object" && m.locales !== null;
}

/** Whether to show the "partly translated / not reviewed" note for a locale. */
export function noteKind(entry: Pick<ManifestEntry, "status" | "coverage"> | undefined, tag: string): "none" | "partial" | "machine" {
  if (tag === "en") return "none";
  if (!entry) return "machine";
  if (entry.coverage < 1 || entry.status === "partial") return "partial";
  return entry.status === "reviewed" ? "none" : "machine";
}
